// Generated from src/registry/sources/control-ui/recipes/kbd.css by scripts/gen-knob-contracts.ts — run `bun run sync:knobs`.
export const kbdKnobs = [
  "--cui-kbd-radius",
  "--cui-kbd-background",
  "--cui-kbd-foreground",
  "--cui-kbd-border-color",
  "--cui-kbd-shadow",
  "--cui-kbd-padding-inline",
  "--cui-kbd-font-size",
  "--cui-kbd-font-weight",
] as const;
export type KbdKnobStyle = Partial<Record<(typeof kbdKnobs)[number], string>>;

@layer components {
  :where([data-control-family="kbd"][data-slot="root"]) {
    block-size: calc(var(--spacing) * 5);
    min-inline-size: calc(var(--spacing) * 5);
    gap: calc(var(--spacing) * 1);
    padding-inline: var(--cui-kbd-padding-inline);
    --cui-kbd-padding-inline: calc(var(--spacing) * 1.5);
    --cui-kbd-font-size: var(--text-micro);
    --cui-kbd-font-weight: var(--font-weight-medium);
    --cui-kbd-radius: var(--radius-control);
    --cui-kbd-background: oklch(from var(--card) l c h / 0.6);
    --cui-kbd-foreground: var(--muted-foreground);
    --cui-kbd-border-color: var(--control-rim);
    --cui-kbd-shadow: var(--shadow-sm);
    border-radius: var(--cui-kbd-radius);
    background: var(--cui-kbd-background);
    box-shadow:
      inset 0 0 0 var(--control-rim-width) var(--cui-kbd-border-color),
      var(--cui-kbd-shadow);
    color: var(--cui-kbd-foreground);
    font-size: var(--cui-kbd-font-size);
    font-family: var(--font-sans);
    font-weight: var(--cui-kbd-font-weight);
  }

  :where([data-control-family="kbd"][data-slot="root"][data-variant="ghost"]) {
    min-inline-size: 0;
    padding-inline: 0;
    background: transparent;
    box-shadow: none;
  }

  :where([data-control-family="button"]:is([data-variant="solid"], [data-variant="scrim"]) [data-control-family="kbd"][data-slot="root"]) {
    --cui-kbd-background: oklch(from currentColor l c h / 0.16);
    --cui-kbd-foreground: currentColor;
    --cui-kbd-border-color: oklch(from currentColor l c h / 0.2);
    --cui-kbd-shadow: 0 0 transparent;
  }

  @media (forced-colors: active) {
    :where([data-control-family="kbd"][data-slot="root"]:not([data-variant="ghost"])) {
      outline: 1px solid CanvasText;
      outline-offset: -1px;
    }
  }

  :where([data-control-family="kbd"][data-slot="group"]) {
    gap: calc(var(--spacing) * 1);
  }
}

@property --cui-kbd-radius {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-kbd-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-kbd-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-kbd-border-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-kbd-shadow {
  syntax: "*";
  inherits: true;
}

@property --cui-kbd-padding-inline {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-kbd-font-size {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-kbd-font-weight {
  syntax: "<number>";
  inherits: true;
  initial-value: 400;
}

import type { ComponentProps, CSSProperties } from "react";

import type { KbdKnobStyle } from "@/components/control-ui/knob-contracts/kbd-knobs";
import { cn } from "@/components/control-ui/lib/cn";

export const kbdVariants = ["default", "ghost"] as const;

export type KbdVariant = (typeof kbdVariants)[number];

export type KbdProps = Omit<ComponentProps<"kbd">, "style"> & { variant?: KbdVariant; style?: CSSProperties & KbdKnobStyle };

export function Kbd({ variant = "default", className, ...props }: KbdProps) {
  return (
    <kbd
      data-control-ui="kbd"
      data-control-family="kbd"
      data-slot="root"
      data-variant={variant}
      className={cn("inline-flex select-none items-center justify-center", className)}
      {...props}
    />
  );
}

export type KbdGroupProps = Omit<ComponentProps<"span">, "style"> & { style?: CSSProperties & KbdKnobStyle };

export function KbdGroup({ className, ...props }: KbdGroupProps) {
  return (
    <span
      data-control-ui="kbd"
      data-control-family="kbd"
      data-slot="group"
      className={cn("inline-flex items-center", className)}
      {...props}
    />
  );
}
